//! Exact two-phase constructor/appearance raw-source DATA, no source completion authority.
use crate::{captured_api_pages as fund,captured_generator_budget::Budget,captured_raw_file::Config,captured_reactive_reads::Failure,captured_allow_annotations::{Operation,PatternOperation},reactive_raw_policy_pages::RawPolicyPages};
use std::{io,sync::Arc};
#[derive(Clone,Copy,Debug,Eq,PartialEq)]pub enum Kind{Constructor,Look}
impl Kind{pub fn name(self)->&'static str{match self{Self::Constructor=>"sys/dx_constructor_shadow",Self::Look=>"sys/dx_look_side_effects"}}pub fn metadata(self)->&'static crate::lint::Meta{static C:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();static L:std::sync::OnceLock<crate::lint::Meta>=std::sync::OnceLock::new();let(name,rules,cell)=match self{Self::Constructor=>(crate::allow_registry_fields::sys_dx_constructor_shadow::SCOPE_MODULE_NAME,crate::allow_registry_fields::sys_dx_constructor_shadow::RULES,&C),Self::Look=>(crate::allow_registry_fields::sys_dx_look_side_effects::SCOPE_MODULE_NAME,crate::allow_registry_fields::sys_dx_look_side_effects::RULES,&L)};cell.get_or_init(||crate::dm::sys::module_metadata(&crate::dm::sys::SysModule{name,rules,..crate::dm::sys::SysModule::DEFAULT},crate::lint::ScanKind::Tree))}}
enum Facts{Constructor(Vec<crate::sys_constructor_shadow_policy::ProcFact>),Look(Vec<String>)}
struct Row{relative:String,facts:Facts}
enum Context{Constructor(crate::sys_constructor_shadow_policy::Context),Look(std::collections::HashSet<String>)}
struct Phase{budget:Arc<Budget>,complete:bool}impl Drop for Phase{fn drop(&mut self){if !self.complete{self.budget.keep_failed_scratch()}}}
fn oom(b:&Budget)->Failure{b.deny();Failure::Operational(io::ErrorKind::OutOfMemory.into())}
fn selected(kind:Kind,config:&Config,relative:&str)->bool{!config.policy_path_exempt(kind.name(),kind.metadata().group,relative)}
pub fn collect(pages:&dyn RawPolicyPages,kind:Kind,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>)->Result<fund::ApiData,Failure>{collect_using(pages,kind,config,root,poll,None)}
pub fn collect_with_patterns(pages:&dyn RawPolicyPages,kind:Kind,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:&dyn crate::native_pattern::Provider)->Result<fund::ApiData,Failure>{collect_using(pages,kind,config,root,poll,Some(patterns))}
fn collect_using(pages:&dyn RawPolicyPages,kind:Kind,config:&Config,root:&Arc<Budget>,poll:&dyn Fn()->io::Result<()>,patterns:Option<&dyn crate::native_pattern::Provider>)->Result<fund::ApiData,Failure>{fund::checked(root,poll)?;let mut phase=Phase{budget:Budget::scoped_temporaries(root).map_err(|_|oom(root))?,complete:false};let b=&phase.budget;let pending=(||{
 let mut facts=Vec::new();let mut caps=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;let file=views.source_file()?;if relative!=file.rel{return Err("shadow/look original index path differs".into())}let local=views.allocation_budget(root);let mut keep=PatternOperation{budget:b,poll,patterns};let mut temp=PatternOperation{budget:local,poll,patterns};
 if kind==Kind::Constructor&&crate::tree::CODE_DM.matches_path(relative){let mut markers=Vec::new();let mut count=0;let found=crate::captured_marker_rows::collect_file_funded(relative,views.marker()?,local,local,&["CAPABILITY_TYPE","CAPABILITY_DEF"],false,false,false,&mut markers,&mut count,&mut||fund::checked(local,poll));match found{Err(Failure::Operational(error))=>return Err(Failure::Operational(error)),other=>{fund::checked(local,poll)?;other?;}}for marker in markers{if let Some(value)=crate::sys_constructor_shadow_policy::cap_type(&marker.name,&marker.args,&mut keep)?{fund::row(b,poll,&mut caps)?;caps.push(value);}}}
 if selected(kind,config,relative){let actual_fixture=patterns.map(|provider|crate::raw_fixture_policy::Fixture::scanned(root,poll,provider,file)).transpose().map_err(pattern_failure)?;let compatibility=crate::raw_fixture_policy::Fixture::legacy();let fixture=actual_fixture.as_ref().unwrap_or(&compatibility);let pending=match kind{Kind::Constructor=>crate::sys_constructor_shadow_policy::file_facts(file,&mut keep,&mut temp).map(Facts::Constructor),Kind::Look=>if actual_fixture.is_some(){crate::sys_look_effects_policy::names_with_fixture(file,&mut keep,&mut temp,fixture).map(Facts::Look)}else{crate::sys_look_effects_policy::names_in_file_using(file,&mut keep,&mut temp).map(Facts::Look)}};if let Some(error)=fixture.take_scan_failure(){return Err(pattern_failure(error))}let value=pending?;if actual_fixture.is_some(){fixture.finish_scan().map_err(pattern_failure)?;}fund::row(b,poll,&mut facts)?;facts.push(Row{relative:fund::own(b,poll,relative)?,facts:value});}fund::checked(local,poll)?;Ok(true)})?{return Err("shadow/look original index stopped before EOF".into())}
 b.charge(facts.len().checked_mul(4*std::mem::size_of::<Row>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;facts.sort_by(|a,b|a.relative.cmp(&b.relative));let mut control=PatternOperation{budget:b,poll,patterns};let context=match kind{Kind::Constructor=>{let actual_fixture=patterns.map(|provider|crate::raw_fixture_policy::Fixture::native_patterns(root,poll,provider));let compatibility=crate::raw_fixture_policy::Fixture::legacy();let fixture=actual_fixture.as_ref().unwrap_or(&compatibility);let rows=facts.iter().flat_map(|row|match &row.facts{Facts::Constructor(v)=>v.as_slice(),_=>&[]});let pending=if actual_fixture.is_some(){crate::sys_constructor_shadow_policy::context_with_fixture(rows,&caps,&mut control,fixture)}else{crate::sys_constructor_shadow_policy::context(rows,&caps,&mut control)};if let Some(error)=fixture.take_scan_failure(){return Err(pattern_failure(error))}let value=pending?;if actual_fixture.is_some(){fixture.finish_scan().map_err(pattern_failure)?;}Context::Constructor(value)},Kind::Look=>Context::Look(crate::sys_look_effects_policy::merge(facts.iter().filter_map(|row|match &row.facts{Facts::Look(v)=>Some(v),_=>None}),&mut control)?)};
 let mut batches=Vec::new();if !pages.for_each(&mut|relative,views|{fund::checked(b,poll)?;if !selected(kind,config,relative){return Ok(true)}let local=views.allocation_budget(root);let file=views.source_file()?;if relative!=file.rel{return Err("shadow/look original judge path differs".into())}let mut keep=PatternOperation{budget:b,poll,patterns};let mut temp=PatternOperation{budget:local,poll,patterns};let(first,second)=match &context{Context::Constructor(context)=>{let row=facts.binary_search_by(|row|row.relative.as_str().cmp(relative)).map_err(|_|Failure::from("constructor selected source absent from actual index"))?;let Facts::Constructor(procs)=&facts[row].facts else{return Err("constructor source facts differ".into())};crate::sys_constructor_shadow_policy::judge(procs,context,&mut keep)?},Context::Look(names)=>{let actual_fixture=patterns.map(|provider|crate::raw_fixture_policy::Fixture::scanned(root,poll,provider,file)).transpose().map_err(pattern_failure)?;let compatibility=crate::raw_fixture_policy::Fixture::legacy();let fixture=actual_fixture.as_ref().unwrap_or(&compatibility);let pending=if actual_fixture.is_some(){crate::sys_look_effects_policy::judge_with_fixture(file,names,&mut keep,&mut temp,fixture)}else{crate::sys_look_effects_policy::judge_using(file,names,&mut keep,&mut temp)};if let Some(error)=fixture.take_scan_failure(){return Err(pattern_failure(error))}let value=pending?;if actual_fixture.is_some(){fixture.finish_scan().map_err(pattern_failure)?;}(value,Vec::new())}};let first=crate::captured_sys_fields_pages::record_rows_borrowed_with_patterns(&views,first,&[],&[],root,poll,patterns)?;let second=crate::captured_sys_fields_pages::record_rows_borrowed_with_patterns(&views,second,&[],&[],root,poll,patterns)?;fund::row(b,poll,&mut batches)?;batches.push((fund::own(b,poll,relative)?,first,second));Ok(true)})?{return Err("shadow/look selected judge stopped before EOF".into())}
 b.charge(batches.len().checked_mul(4*std::mem::size_of::<(String,fund::ApiData,fund::ApiData)>()).and_then(|n|n.checked_add(128)).ok_or_else(||oom(b))?).map_err(|_|oom(b))?;batches.sort_by(|a,b|a.0.cmp(&b.0));let mut data=fund::empty();let mut seconds=Vec::new();fund::reserve_append(b,poll,&mut seconds,batches.len())?;for(_,first,second)in batches{fund::append(&mut data,first,root,poll)?;seconds.push(second);}for second in seconds{fund::append(&mut data,second,root,poll)?;}fund::checked(b,poll)?;Ok(data)
})();if matches!(&pending,Err(Failure::Operational(_))){return pending}fund::checked(root,poll)?;phase.complete=pending.is_ok();drop(phase);pending}

fn pattern_failure(actual:crate::derived_selftest_policy::Failure)->Failure{match actual{crate::derived_selftest_policy::Failure::Operational(actual)=>Failure::Operational(actual),crate::derived_selftest_policy::Failure::Assertion(message)=>Failure::Unsupported(message)}}
